from collections import defaultdict, deque

def solution(data):
    # Parse input
    lines = data.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    pairs = []
    for i in range(2, 2 + m):
        u, v = map(int, lines[i].split())
        pairs.append((u - 1, v - 1))  # Convert to 0-indexed

    def prime_factor_count(n, p):
        """Count exponent of prime p in n"""
        count = 0
        while n % p == 0:
            count += 1
            n //= p
        return count

    def prime_factors(n):
        """Get all prime factors of n"""
        factors = {}
        d = 2
        temp = n
        while d * d <= temp:
            while temp % d == 0:
                factors[d] = factors.get(d, 0) + 1
                temp //= d
            d += 1
        if temp > 1:
            factors[temp] = factors.get(temp, 0) + 1
        return factors

    # Collect all unique primes
    all_primes = set()
    for num in a:
        all_primes.update(prime_factors(num).keys())

    def max_flow(S, T, capacity):
        """Edmonds-Karp algorithm for bipartite matching with capacities"""
        flow = 0

        # Copy capacity for BFS/DFS
        remaining = defaultdict(lambda: defaultdict(int))
        for u in capacity:
            for v in capacity[u]:
                remaining[u][v] = capacity[u][v]

        visited = set()
        parent = {}
        queue = [S]

        while S in remaining and S in capacity:
            queue = deque([S])
            while queue:
                # BFS until we find a path to T
                u = queue.popleft()
                if u == T:
                    break

                for v in capacity[u]:
                    if v not in visited and capacity[u][v] > 0:
                        visited.add(v)
                        parent[v] = u
                        queue.append(v)
                        if v == T:
                            break

                if u == T and T in visited:
                    break

            if T not in parent:
                break

            # Find path and min capacity
            path_flow = float('inf')
            v = T
            while v != S:
                u = parent[v]
                path_flow = min(path_flow, capacity[u][v])
                v = u

            # Push flow
            flow += path_flow
            v = T
            while v != S:
                u = parent[v]
                capacity[u][v] -= path_flow
                capacity[v][u] += path_flow
                v = u

            # Clear visited
            visited.clear()

        return flow

    def solve_for_prime(p):
        """Calculate max operations using only prime p"""
        S, T = 0, 2 * n + 1
        capacity = defaultdict(lambda: defaultdict(int))

        # Add edges from source to even positions
        for i in range(n):
            exp = prime_factor_count(a[i], p)
            if exp > 0:
                capacity[S][2 * i] = exp

        # Add edges from odd positions to sink
        for i in range(n):
            exp = prime_factor_count(a[i], p)
            if exp > 0:
                capacity[2 * i + 1][T] = exp

        # Add edges for good pairs
        for u, v in pairs:
            if (u + 1) % 2 != (v + 1) % 2:  # Different parity (one even, one odd)
                # u is even position, v is odd position
                capacity[2 * u][2 * v + 1] = float('inf')
                capacity[2 * v + 1][2 * u] = float('inf')

        return max_flow(S, T, capacity)

    total_operations = 0
    for p in all_primes:
        total_operations += solve_for_prime(p)

    return str(total_operations) + '\n'

