def is_bitonic(arr: List[int]) -> bool:
    """Check if array is bitonic (increases then decreases)"""
    if len(arr) <= 1:
        return True

    # Find the tallest peak
    peak = 0
    for i in range(1, len(arr)):
        if arr[i] > arr[peak]:
