import math

def square_free_part(n):
    """Get the square-free part of n by dividing out the largest square factor."""
    result = 1
    i = 2
    while i * i <= n:
        while n % (i * i) == 0:
            n //= (i * i)
        i += 1
    while n % 4 == 0:
        n //= 4
    return n

def mod_pow(base, exp, mod):
    """Fast modular exponentiation."""
    result = 1
    base %= mod
    while exp:
        if exp & 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exp >>= 1
