            dfs2(u, scc_count)
            scc_count += 1

    # Compute GCD of cycle lengths for each SCC (any root works in the SCC)
    scc_gcds = {}

    for scc_id_val in range(scc_count):
        nodes = nodes_by_scc[scc_id_val]
        root = nodes[0]

        # BFS from root within the SCC
        dist = {root: 0}
        visited_bfs = {root}

        # Reverse edges for reachability within SCC (for proper cycle detection)
        in_scc = {n for n in nodes}

        q_bfs = deque([root])
        while q_bfs:
            u = q_bfs.popleft()
            for v, w in adj[u]:
                if v in in_scc and v not in visited_bfs:
                    visited_bfs.add(v)
                    dist[v] = dist[u] + w
                    q_bfs.append(v)

        # Compute GCD of fundamental cycles through root
        g = 0
        for u in nodes:
            for v, w in adj[u]:
                if v in in_scc and v != u:
                    if v in dist:
                        # This edge forms a potential cycle
                        cycle_len = dist[u] + w
                        if v == root:
                            cycle_len = cycle_len + dist[u]
                        g = gcd(g, cycle_len)

        scc_gcds[scc_id_val] = g

    # Answer queries
    results = []
    for v, s, t in queries:
        # If sitting still, check if already 0
        if s == 0:
            results.append("YES")
            continue

        my_scc = scc_id[v]
        g = scc_gcds.get(my_scc, 0)

        # For the odometer to show 0:
        # (s + total_distance) % t == 0
        # total_distance ≡ -s (mod t)
